app.delete('/api/tenants/:tenantId/payment_methods/:payment_id', verifyJwtToken, requireRole('admin'), async (req, res) => {
    const { tenantId, payment_id } = req.params;
    if (req.user.tenantId !== tenantId) {
        return res.status(403).json({ error: 'Access denied to foreign tenant' });
    }
    const deleted = await PaymentMethod.deleteOne({ _id: payment_id, tenantId: tenantId });
    if (deleted.deletedCount === 0) return res.status(404).json({ error: 'PaymentMethod not found' });
    return res.json({ success: true, message: 'PaymentMethod deleted' });
});

