app.delete('/api/tenants/:tenantId/medical_records/:record_id', verifyJwtToken, requireRole('admin'), async (req, res) => {
    const { tenantId, record_id } = req.params;
    if (req.user.tenantId !== tenantId) {
        return res.status(403).json({ error: 'Access denied to foreign tenant' });
    }
    const deleted = await MedicalRecord.deleteOne({ _id: record_id, tenantId: tenantId });
    if (deleted.deletedCount === 0) return res.status(404).json({ error: 'MedicalRecord not found' });
    return res.json({ success: true, message: 'MedicalRecord deleted' });
});

